#include "low_peak_energy.h"
#include <iostream>
int main(){low_peak_energy::Feedback f;char op;unsigned ms;float a,b,c,d,e,rate,rpm,v,prev,tau,goal,initial,base;float fl=0,fr=0;int ok,foot,fvalid=0;unsigned width,cap;while(std::cin>>op>>ms){if(op=='N'){std::cin>>a>>ok;f.negative(ms,a,ok);}else if(op=='P'){std::cin>>a>>b>>c>>d>>ok>>foot>>e>>base;fvalid=foot;fl=e;fr=base;f.positive(ms,a,b,0.f,c,d,ok,foot,e,base);}else if(op=='C'){std::cin>>rate>>rpm>>v>>prev>>tau>>goal>>initial>>base>>width>>cap;wheel_work_energy_control::State s{rate,rpm,v,true,prev};s.absolute_reference=true;s.target_deg=8;lateral_energy::Geometry g;lateral_energy::CurrentTable tab;tab.prepare(tau);if(f.eligibleForCorrection(ms,cap,base,fvalid,fl,fr)){auto choice=low_peak_energy::choose(g,s,tab,goal,initial,base,0,f.bias(),cap,f.lastWidth());if(choice.valid && choice.width_ms!=width){std::cout<<"first_changed_ms="<<ms<<" baseline="<<width<<" candidate="<<choice.width_ms<<" bias_mJ="<<f.bias()<<"\n";return 0;}}f.command(ms,1,true,400,width,5,rate,rpm,v);}}std::cout<<"no changed command bias="<<f.bias()<<" active="<<f.active()<<"\n";}
